class Circle:
    def __init__(self, radius):
        self.radius = radius

    @property
    def area(self):
        return 3.14159 * self.radius ** 2


c = Circle(2)
print(round(c.area, 2))

c.radius = 3
print(round(c.area, 2))

class Temperature:
    def __init__(self, celsius):
        self.celsius = celsius

    @property
    def celsius(self):
        return self._c

    @celsius.setter
    def celsius(self, value):
        if value < -273.15:
            raise ValueError("低于绝对零度")
        self._c = value


t = Temperature(25)
print(t.celsius)

try:
    t.celsius = -300
except ValueError as exc:
    print("拒收：", exc)

class Point:
    __slots__ = ("x", "y")

    def __init__(self, x, y):
        self.x = x
        self.y = y


p = Point(1, 2)
print(hasattr(p, "__dict__"))

try:
    p.z = 3
except AttributeError as exc:
    print(type(exc).__name__)

class Slot:
    __slots__ = ("a",)

    def __init__(self):
        self.a = 1


s = Slot()
print(s.a)
